(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin(x*0.035-t*0.5)*8 + Math.cos(y*0.03+t*0.45)*6;
  const w2y = Math.cos(y*0.032+t*0.55)*8 + Math.sin(x*0.028-t*0.4)*6;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 1],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 3],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 4],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 5],
    [80+Math.sin(t*0.7+3)*70, 40+Math.cos(t*0.6+2)*50, 0.11, 2.1, 0],
    [400+Math.cos(t*0.45+1)*60, 220+Math.sin(t*0.65+4)*40, 0.13, 1.8, 1],
    [200+Math.sin(t*0.55+6)*90, 200+Math.cos(t*0.75+3)*60, 0.05, 2.4, 2],
    [300+Math.cos(t*0.38+2)*110, 30+Math.sin(t*0.48+1)*45, 0.09, 2.0, 3]
  ];
  let aS = 0, iS = 0, crs = 0;
  for (const [sX, sY, f, sp, grp] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp);
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
    crs += Math.sin(d*f*1.3 - t*sp*0.8 + grp*1.2);
  }
  const act = aS/10, inh = iS/10, crv = crs/10;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1) + Math.sin(sx*0.05+sy*0.01-t*0.6))/3
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2
    + Math.sin(sx*0.08+t*1.8)*Math.cos(sy*0.07-t*1.3)*0.15;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2) + Math.sin(dist*0.06-ang*2+t*0.9))*0.33;
  const cx2 = 120+Math.sin(t*0.3)*60, cy2 = 180+Math.cos(t*0.4)*40;
  const dist2 = Math.sqrt((sx-cx2)**2 + (sy-cy2)**2), ang2 = Math.atan2(sy-cy2, sx-cx2);
  const spiral2 = (Math.sin(dist2*0.06+ang2*3-t*1.8) + Math.sin(dist2*0.045-ang2*5+t*1.1))*0.25;
  const rd1 = Math.tanh((act - inh*0.7 + bg*0.3 + spiral)*2.2);
  const rd2 = Math.tanh((crv*0.6 - act*0.3 + spiral2 + bg*0.2)*1.8);
  const coupling = Math.tanh((rd1 + rd2*0.5)*1.5);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5 + Math.sin(sx*0.2-sy*0.08+t*0.7)*0.3)*1.5)*0.3;
  const blend = coupling*0.7 + cell*0.3, v = blend*0.5+0.5;
  const pal = [
    [8,12,52],[15,45,85],[22,85,115],[30,135,125],[80,170,105],
    [165,195,75],[215,170,50],[210,105,60],[175,50,55],[110,28,60],
    [55,18,65],[8,12,52]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.8+Math.sin(coupling*Math.PI)*0.2;
  const edge = Math.abs(coupling)>0.7?1.15:1.0;
  const fi = Math.min(i+1, pal.length-2);
  const r = (pal[i][0]+(pal[fi][0]-pal[i][0])*f)*lum*edge;
  const g = (pal[i][1]+(pal[fi][1]-pal[i][1])*f)*lum*edge;
  const b = (pal[i][2]+(pal[fi][2]-pal[i][2])*f)*lum*edge;
  const shift = Math.sin(t*0.15)*0.06;
  const vx = (x-240)/240, vy = (y-120)/120;
  const vig = 1 - (vx*vx+vy*vy)*0.18;
  return [
    Math.min(255, (r*(1+shift) + shift*15)*vig)|0,
    Math.min(255, g*vig)|0,
    Math.min(255, (b*(1-shift) - shift*10)*vig)|0
  ];
}
